"""Functional commercial pages; all contacts continue through the existing BIA numbers."""
from html import escape as esc
from offers_page import offers_body

def support_page(kind,data,icon,cta,money,finance,units):
 titles={'ofertas':('Modelos e preços','Encontre a sua próxima Bajaj.','Compare os seis modelos e consulte disponibilidade e condições com a BIA da unidade escolhida.'),'financiamento':('Financiamento','Sua Bajaj começa com uma conversa.','Escolha o modelo, a entrada e o prazo desejados. A BIA continua a solicitação e a análise no WhatsApp.'),'test-ride':('Test ride','Antes de escolher, sinta na prática.','Solicite um test ride em Rio Preto ou Bauru. A equipe confirma modelo disponível, requisitos, data e horário.'),'pos-venda':('Pós-venda','O cuidado continua a cada quilômetro.','Revisões, manutenção, peças genuínas e orientações sobre sua Bajaj. Fale com a unidade que está perto de você.'),'unidades':('Nossas unidades','Rio Preto ou Bauru.<br>Escolha seu caminho.','Duas unidades para acompanhar você na compra e no cuidado com a sua Bajaj.'),'a-interiorsp':('Bajaj InteriorSP','A sua Bajaj.<br>Aqui no interior.','Concessionária autorizada Bajaj em São José do Rio Preto e Bauru. Atendimento local antes, durante e depois da compra.')}
 label,title,description=titles[kind]
 hero=f'<section class="service-hero"><nav aria-label="Você está aqui"><a href="/">Início</a><span aria-hidden="true">/</span><span aria-current="page">{label}</span></nav><p class="service-eyebrow">Bajaj InteriorSP · {label}</p><h1>{title}</h1><p>{description}</p></section>'
 if kind=='ofertas':body=offers_body(data,icon,money)
 elif kind=='financiamento':body=finance()+'<section class="section service-note"><h2>Você informa a intenção.<br>A BIA continua o atendimento.</h2><p>Não calculamos parcelas nem aprovamos crédito no site. Não é necessário informar CPF ou enviar documentos aqui. Taxas, prazos e aprovação dependem da análise e da proposta apresentada no atendimento.</p><p>A abertura do WhatsApp apenas prepara a mensagem. Envie-a para iniciar a conversa.</p></section>'
 elif kind in ['test-ride','pos-venda']:
  service_options=''.join(f'<option value="{i}">{name}</option>' for i,name in [('revisao','Revisão'),('manutencao','Manutenção'),('pecas','Peças genuínas'),('acessorios','Acessórios'),('garantia','Garantia e manual')])
  intro='<h2>Qual é o próximo cuidado?</h2><p>Conte sua necessidade e continue pelo WhatsApp da unidade. A equipe confirma preços, peças e horários no atendimento.</p>' if kind=='pos-venda' else '<h2>Conheça de perto.</h2><p>Escolha o modelo e a unidade. Se quiser, informe uma data de preferência; a equipe precisa confirmar a disponibilidade antes da visita.</p>'
  model_options='<option value="">Quero ajuda para escolher</option>'+''.join(f'<option value="{m["id"]}">{m["name"]}</option>' for m in data['models'])
  form=f'<form class="service-request" data-service-form="{kind}"><label for="service-model">Modelo <span>(opcional)</span></label><select id="service-model" name="model">{model_options}</select>'
  if kind=='pos-venda':form+=f'<label for="service-intent">O que você precisa?</label><select id="service-intent" name="intent">{service_options}</select>'
  else:form+='<label for="service-date">Data de preferência <span>(opcional)</span></label><input id="service-date" type="date" name="date"><small>A data é uma preferência. A equipe confirma o horário no WhatsApp.</small>'
  form+=f'<label for="service-unit">Unidade</label><select id="service-unit" name="unit" required><option value="">Escolha sua unidade</option>'+''.join(f'<option value="{u["id"]}">{u["name"]}</option>' for u in data['units'])+'</select><label for="service-detail">Quer acrescentar algo? <span>(opcional)</span></label><textarea id="service-detail" name="detail" rows="3" maxlength="500" placeholder="Conte sua necessidade, sem documentos ou dados sensíveis."></textarea><p class="form-error" role="alert" data-service-error hidden></p><button class="button" type="submit">Continuar no WhatsApp '+icon('arrow')+'</button><p class="fine">Nada é enviado ou agendado ao abrir o WhatsApp. Envie a mensagem e aguarde a confirmação da equipe.</p><p data-service-fallback hidden>Mensagem preparada. <a class="text-link" data-service-link target="_blank" rel="noopener">Abrir WhatsApp →</a></p></form>'
  body='<section class="section service-request-grid"><div>'+intro+cta('Prefiro falar direto com a BIA','revisao' if kind=='pos-venda' else 'test')+'</div>'+form+'</section>'
  if kind=='pos-venda':body+='<section class="section service-note"><h2>Peças, revisão e garantia.</h2><p>Informe modelo e ano durante a conversa para consultar a aplicação correta das peças e o plano de manutenção. A garantia segue os termos da fabricante e do manual de cada modelo.</p><a class="text-link" href="https://bajaj.com.br/pos-vendas/" target="_blank" rel="noopener">Consultar orientações oficiais Bajaj ↗</a></section>'
  body+=units()
 elif kind=='unidades':body=store_units(data,icon,cta)+'<section class="section service-note"><h2>Planeje a sua visita.</h2><p>Converse com a BIA da unidade para confirmar o horário de atendimento, a disponibilidade do modelo e os serviços desejados antes de ir até a loja.</p><a class="button" href="/test-ride/">Solicitar test ride '+icon('arrow')+'</a></section>'
 else:body='<section class="section introduction"><div class="intro-image"><img src="/assets/unidade-bauru-showroom-press-large.webp" srcset="/assets/unidade-bauru-showroom-press-small.webp 640w, /assets/unidade-bauru-showroom-press-large.webp 1024w" sizes="(max-width:767px) 90vw, 43vw" width="1024" height="768" alt="Showroom da Bajaj InteriorSP de Bauru, com motocicletas expostas, em foto de divulgação da inauguração." loading="lazy"><small>InteriorSP Bauru · Divulgação Bajaj.</small></div><div><h2>Atendimento local.<br>Do primeiro contato em diante.</h2><p>A InteriorSP aproxima a linha Bajaj de quem está em São José do Rio Preto, Bauru e região. Conheça os modelos, consulte condições e escolha a unidade para continuar a conversa com a BIA.</p><p>Conte com atendimento para test ride, revisão, manutenção e consulta de peças genuínas. A equipe confirma disponibilidade, requisitos e próximos passos.</p><div class="actions"><a class="button" href="/ofertas/">Explorar modelos e preços '+icon('arrow')+'</a><a class="text-link" href="/pos-venda/">Conhecer o pós-venda '+icon('arrow')+'</a></div></div></section>'+units()
 return '<div class="service-page">'+hero+body+'</div>',label,description


def store_units(data,icon,cta):
 import json
 from pathlib import Path
 photos=json.loads(Path(__file__).with_name('store-photos.json').read_text())
 cards=[]
 for u in data['units']:
  photo=photos[u['id']];small=photo['variants']['small'];large=photo['variants']['large']
  srcset=', '.join(f'/assets/{v["file"]} {v["width"]}w' for v in [small,large])
  cards.append(f'''<article class="store-unit" id="unidade-{u['id']}"><figure class="store-unit-photo"><img src="/assets/{large['file']}" srcset="{srcset}" sizes="(max-width:1024px) 90vw, 45vw" width="{large['width']}" height="{large['height']}" alt="{esc(photo['alt'])}" loading="lazy" decoding="async"><figcaption><span>Foto: {esc(photo['credit'])} · {photo['published'][:4]}</span><a href="{esc(photo['source'])}" target="_blank" rel="noopener" aria-label="Ver a fonte da foto da unidade de {u['short']}">Ver fonte ↗</a></figcaption></figure><div class="store-unit-copy"><p class="service-eyebrow">Bajaj InteriorSP · {u['short']}</p><h2>{u['name']}</h2><address>{u['address']}<br>CEP {u['cep']}</address><p class="store-phone">WhatsApp {u['display']}</p><div class="actions">{cta('Falar com a BIA',unit=u['id'])}<a class="text-link google-maps-link" href="{esc(u['mapsDirections'])}" target="_blank" rel="noopener noreferrer" aria-label="Como chegar à unidade de {u['name']} pelo Google Maps (abre em nova aba)">Como chegar {icon('maps')}</a></div><a class="text-link store-test" href="/test-ride/">Solicitar test ride {icon('arrow')}</a><small>INTERIORSP MOTOS LTDA · CNPJ {u['cnpj']}</small></div></article>''')
 return '<section class="section store-units" id="unidades" aria-label="Conheça as unidades InteriorSP"><div class="store-unit-list">'+''.join(cards)+'</div></section>'
